INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q10751080', '1811 Independence Movement', 'The 1811 Independence Movement (Spanish: Movimiento de Independencia de 1811), known in El Salvador as the First Shout of Independence (Primer Grito de Independencia), was the first of a series of revolts in Central America in modern-day El Salvador against Spanish rule and dependency on the Captaincy General of Guatemala. The independence movement was led by prominent Salvadoran and Central American figures such as José Matías Delgado, Manuel José Arce, and Santiago José Celis.', 1811, 11, 5, NULL, NULL, NULL, 'day', '5 November 1811', 30, 'https://en.wikipedia.org/wiki/1811_Independence_Movement'),
  ('Q17633452', 'First Central American Civil War', 'The First Central American Civil War (Spanish: Primera Guerra Civil Centroamericana), also known as the Federal War of 1826–1829 (Guerra Federal de 1826–1829), was a civil political and military conflict within the Federal Republic of Central America which lasted from 1826 until 1829. The civil war was fought between liberals led by General Francisco Morazán and conservatives led by General Manuel José Arce, the president of Central America and a former liberal.', 1826, 9, 6, 1829, 6, 25, 'day', '6 September 1826 – 25 June 1829', 37, 'https://en.wikipedia.org/wiki/First_Central_American_Civil_War'),
  ('Q2888283', 'Battle of Chalchuapa', 'The Battle of Chalchuapa (Spanish: Batalla de Chalchuapa) was a battle between the military forces of El Salvador and Guatemala from 1–2 April 1885. Guatemalan President Justo Rufino Barrios was killed during the battle.', 1885, 4, 1, 1885, 4, 2, 'day', '1 April 1885 – 2 April 1885', 37, 'https://en.wikipedia.org/wiki/Battle_of_Chalchuapa'),
  ('Q5918797', 'Barrios'' War of Reunification', 'Barrios'' War of Reunification, also known as Barrios'' great attempt (Spanish: intentona de Barrios), was a war initiated by Guatemalan President Justo Rufino Barrios in 1885 with the goal of reunifying Central America. Of the five Central American countries, only Honduras supported Barrios'' reunification effort; Costa Rica, El Salvador, and Nicaragua opposed it, as did Mexico.', 1885, 2, 28, 1885, 4, 14, 'day', '28 February 1885 – 14 April 1885', 26, 'https://en.wikipedia.org/wiki/Barrios''_War_of_Reunification'),
  ('Q9068529', 'Revolution of the 44', 'The Revolution of the 44 (Spanish: Revolución de los 44) was a military rebellion led by a group of Salvadoran generals and landowners, known as "the 44", against the government of President General Carlos Ezeta and Vice President General Antonio Ezeta. The rebellion began in late-April 1894 when rebels captured the western Salvadoran city of Santa Ana, upon which, Ezeta declared a state of siege.', 1894, 4, 29, NULL, NULL, NULL, 'day', '29 April 1894', 30, 'https://en.wikipedia.org/wiki/Revolution_of_the_44'),
  ('Q5776014', 'history of El Salvador from 1931 to 1979', 'The Salvadoran military dictatorship was the period in Salvadoran history when the Armed Forces of El Salvador (FAES) governed the country for almost 48 years from 1931 to 1979. The military dictatorship governed in an authoritarian manner, limited political rights throughout, and maintained its governance through rigged elections.', 1931, 12, 2, 1979, 10, 15, 'day', '2 December 1931 – 15 October 1979', 37, 'https://en.wikipedia.org/wiki/Military_dictatorship_in_El_Salvador'),
  ('Q85722045', '1931 Salvadoran coup d''état', 'The 1931 Salvadoran coup d''état occurred on 2 December 1931 when the Armed Forces of El Salvador overthrew President Arturo Araujo. The Civic Directory (a military junta) ruled El Salvador for two days after the coup until it relinquished power to Brigadier General Maximiliano Hernández Martínez, Araujo''s Vice President and Minister of War, the Navy, and Aviation.', 1931, 12, 2, NULL, NULL, NULL, 'day', '2 December 1931', 34, 'https://en.wikipedia.org/wiki/1931_Salvadoran_coup_d''%C3%A9tat'),
  ('Q939859', '1932 Salvadoran peasant massacre', 'La Matanza (Spanish for ''The Massacre'') refers to a communist-indigenous rebellion that took place in El Salvador between 22 and 25 January 1932. After the revolt was suppressed, it was followed by large-scale government killings in western El Salvador, which resulted in the deaths of 10,000 to 40,000 people.', 1932, NULL, NULL, NULL, NULL, NULL, 'year', '1932', 53, 'https://en.wikipedia.org/wiki/La_Matanza'),
  ('Q223085', 'Hundred Hour War', 'The Football War (Spanish: guerra del fútbol), also known as the Soccer War or the 100 Hour War, was a brief military conflict fought between El Salvador and Honduras in 1969. Existing tensions between the two countries coincided with rioting during a 1970 FIFA World Cup qualifier, hence its nickname.', 1969, 7, 14, 1969, 7, 18, 'day', '14 July 1969 – 18 July 1969', 75, 'https://en.wikipedia.org/wiki/Football_War'),
  ('Q1783607', 'Salvadoran Civil War', 'The Salvadoran Civil War (Spanish: guerra civil de El Salvador) was a twelve-year civil war in El Salvador that was fought between the government of El Salvador that was backed by the United States, against the Farabundo Martí National Liberation Front (FMLN), a coalition of left-wing guerrilla groups that was backed by Cuba under Fidel Castro, Daniel Ortega''s Nicaragua and the Soviet Union. A coup on 15 October 1979 followed by government killings of anti-coup protesters is widely seen as the start of the civil war.', 1979, 10, 15, 1992, 1, 16, 'day', '15 October 1979 – 16 January 1992', 65, 'https://en.wikipedia.org/wiki/Salvadoran_Civil_War'),
  ('Q84806169', '1979 Salvadoran coup d''état', 'The 1979 Salvadoran coup d''état occurred on 15 October when junior officers of the Armed Forces of El Salvador''s Military Youth Movement (MJM) bloodlessly overthrew General Carlos Humberto Romero, the president of El Salvador. The coup leaders established the Revolutionary Government Junta (JRG) that ruled El Salvador until 1982.', 1979, 10, 15, NULL, NULL, NULL, 'day', '15 October 1979', 41, 'https://en.wikipedia.org/wiki/1979_Salvadoran_coup_d''%C3%A9tat'),
  ('Q1414900', 'El Mozote massacre', 'The El Mozote massacre took place in and around the village of El Mozote in the Morazán Department of El Salvador on December 11 and 12, 1981, during the Salvadoran Civil War, when the Salvadoran Army killed more than 811 civilians. The army had arrived in the village on the 10th, following clashes with guerrillas in the area.', 1981, 12, 11, NULL, NULL, NULL, 'day', '11 December 1981', 53, 'https://en.wikipedia.org/wiki/El_Mozote_massacre'),
  ('Q4828607', 'Aviateca Flight 901', 'Aviateca Flight 901 was a scheduled international passenger flight which crashed into the 7,159-foot (2,182 m) San Vicente volcano in El Salvador of a Boeing 737-200 on approach to the Comalapa International Airport on 9 August 1995. The accident killed all 65 passengers and crew on board and is the deadliest aviation disaster to occur in El Salvador.', 1995, 8, 9, NULL, NULL, NULL, 'day', '9 August 1995', 47, 'https://en.wikipedia.org/wiki/Aviateca_Flight_901'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic');
